body {
  font-family: "Inter", system-ui, -apple-system, sans-serif; /* oxirida generic oila */
  font: 400 1rem/1.6 "Inter", sans-serif; /* shorthand: weight size/line-height family */
}

@font-face {
  font-family: "Inter";
  src: url(/fonts/inter.woff2) format("woff2");
  font-weight: 100 900;   /* variable font: oraliq */
  font-display: swap;
}

.row {
  display: flex;
  justify-content: space-between; /* bosh o'q bo'ylab */
  align-items: center;            /* ko'ndalang o'q bo'ylab */
  gap: 16px;                      /* elementlar orasidagi masofa */
  flex-wrap: wrap;                /* sig'masa, yangi qatorga */
}

