code.text:
.grid {
  display: grid;
  grid-template-columns: 200px 1fr 2fr;       /* 1 qat., 1fr + 2fr qolgan joyni 1:2 */
  grid-template-columns: repeat(3, 1fr);       /* 3 ta teng ustun */
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); /* responsiv */
  gap: 16px;
}

