code.text:
.cards { display: grid; grid-template-columns: repeat(3, 1fr); grid-template-rows: auto; }
.card  { display: grid; grid-row: span 3; grid-template-rows: subgrid; }
/* sarlavha, matn va tugma har bir kartada bir xil balandlikda chiqadi */

.gallery { grid-auto-flow: dense; } /* bo'sh kataklarni to'ldirishga urinadi */

.card   { position: relative; }
.badge  { position: absolute; top: 8px; right: 8px; }   /* .card burchagida */
.cover  { position: absolute; inset: 0; }             /* butun .card ni qoplaydi */
.header { position: sticky; top: 0; }

.modal-bg { position: fixed; inset: 0; z-index: 10; }
.card     { opacity: .99; }    /* yangi stacking context! */
/* card ichidagi z-index: 9999 baribir modal-bg dan past, agar card konteksti past bo'lsa */

.list   { max-height: 300px; overflow-y: auto; scroll-behavior: smooth; }
.slider { display: flex; overflow-x: auto; scroll-snap-type: x mandatory; }
.slide  { flex: 0 0 100%; scroll-snap-align: start; }
html    { scrollbar-gutter: stable; }  /* scrollbar paydo bo'lganda sakramasin */

/* mobile-first: avval kichik ekran, keyin min-width bilan kengaytirish */
.cols { display: grid; gap: 16px; }
@media (min-width: 768px) { .cols { grid-template-columns: 1fr 1fr; } }
@media (prefers-reduced-motion: reduce) { * { animation: none; } }
@media (hover: hover) { .btn:hover { background: #eee; } }
img { max-width: 100%; height: auto; }

.sidebar, .main { container-type: inline-size; container-name: box; }

.card { display: grid; gap: 8px; }
@container box (min-width: 400px) {
  .card { grid-template-columns: 120px 1fr; }
}

.title { font-size: clamp(1rem, 4cqw, 2rem); } /* cqw: konteyner kengligining 1% */

:root {
  --brand: #2563eb;
  --gap: 16px;
}
.btn { background: var(--brand); padding: var(--gap, 12px); }  /* fallback: 12px */
.btn.alt { --brand: #dc2626; }  /* faqat shu element va avlodlarida o'zgaradi */

@media (prefers-color-scheme: dark) { :root { --bg: #111; --fg: #eee; } }

@property --angle { syntax: "<angle>"; inherits: false; initial-value: 0deg; }

.card:has(img)          { padding: 0; }        /* ichida rasm bor card */
label:has(input:checked) { font-weight: 700; }
form:focus-within        { outline: 2px solid; } /* ichida fokus bor */
:is(h1, h2, h3) a        { color: inherit; }
:where(.a, .b) p         { margin: 0; }          /* specificity 0 */
li:not(.done)            { }

.card {
  padding: 16px;
  & .title { font-weight: 700; }   /* .card .title */
  &:hover { background: #eee; }    /* .card:hover */
  @media (min-width: 600px) { padding: 24px; }
}

.card {
  transition: transform .2s ease, box-shadow .2s;
}
.card:hover {
  transform: translateY(-4px) scale(1.02);
  transform-origin: center;
}
.rot { rotate: 45deg; scale: 1.2; translate: 10px 0; } /* alohida xususiyatlar */

@keyframes pop {
  0%   { transform: scale(.8); opacity: 0; }
  60%  { transform: scale(1.05); }
  100% { transform: scale(1);  opacity: 1; }
}
.toast {
  animation: pop 400ms ease-out 100ms 1 normal both;
  /* name duration timing delay iteration direction fill-mode */
}

